import{b as o,O as a,g as t,j as l}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"燃烧的大洋：1941—1942，从突袭珍珠港到中途岛战役","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/burning-ocean/index.md","filePath":"读书感悟/电子书架/28.燃烧的大洋：1941—1942，从突袭珍珠港到中途岛战役.md","lastUpdated":1781614933000}'),p={name:"reading/digital/burning-ocean/index.md"};function c(r,e,_,n,i,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="燃烧的大洋-1941—1942-从突袭珍珠港到中途岛战役" tabindex="-1">燃烧的大洋：1941—1942，从突袭珍珠港到中途岛战役 <a class="header-anchor" href="#燃烧的大洋-1941—1942-从突袭珍珠港到中途岛战役" aria-label="Permalink to &quot;燃烧的大洋：1941—1942，从突袭珍珠港到中途岛战役&quot;">​</a></h1><p><code>伊恩·托尔</code> <code>世界史</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 温言在口，大棒在手’，这样才能走得远。</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 理想很丰满，现实很骨感，注定要为你们的狂我自大付出惨重的教训</p><p>📌 日本决策层原来设想，通过突然袭击美国太平洋舰队，完全可以趁美国元气大伤，还没有来得及喘过气、回过味儿的时候，在有利的战略态势下与美国谈判，让美国回到西半球，把亚太留给日本，进而结束战争。</p></blockquote><blockquote><p>💭 开战在我，终战在彼</p><p>📌 在太平洋战争中，日本以自己的惨痛教训告诉世人：大国之间的战争，无论取得多少战术上的胜利，只要战争无法在你的既定条件下结束，都是战略上的失败。而战略上的失败将决定战争的最后结局和历史的走向。</p></blockquote><blockquote><p>💭 日本成就了美国🤣</p><p>📌 日本战略上犯的错误给了美国走上全球权力顶峰的机会。</p></blockquote><blockquote><p>💭 很喜欢这句话</p><p>📌 “雪崩时没有一片雪花是无辜的。”</p></blockquote><blockquote><p>💭 建前和本音</p><p>📌 建前指的是人们向世界展现的面貌，在公共场合表达的观点，或者是迫于阶级或职位必须扮演的角色。本音指的是“真实”或者“真情实感”，只有在亲朋好友面前才会表现出来。摘下面具，向另一个人表现出本音，象征着亲密或者信任，等同于把另一个人视为知己。</p></blockquote><blockquote><p>💭 寒气逼人，哈哈哈哈</p><p>📌 谁都高兴不起来。彻骨的寒冷让所有人都瑟瑟发抖，大家都很想回屋喝杯热茶</p></blockquote><blockquote><p>💭 集权制，会使各方的意见摩擦达到最小化</p><p>📌 人性的弱点是，特别不愿意把自己的部队交给另一个军种指挥。如果我们现在制订由一个人来指挥的计划，那就能解决十分之九的问题</p></blockquote><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><blockquote><p>战争的残酷描绘的栩栩如生，就好像自己也是航母中一名士兵，身临其境的感觉，震撼的同时也深深的感受到了战争的残酷事实。</p></blockquote>',14)])])}const q=o(p,[["render",c]]);export{b as __pageData,q as default};
